class Solution {
  public boolean checkArray(int[] nums, int k) {
    int n = nums.length, applied = 0;
    int[] expire = new int[n + 1]; // how much each window stops contributing at index i
    for (int i = 0; i < n; i++) {
      applied -= expire[i];
      int left = nums[i] - applied;
      if (left < 0) return false;
      if (left > 0) {
        if (i + k > n) return false;
        applied += left;
        expire[i + k] += left;
      }
    }
    return true;
  }
}
